const cfg = $('Config').first().json;
const uniq = (rows, key) => { const seen = {}; const out = []; rows.forEach(r => { const k = String(r[key] || '').trim(); if (k && !seen[k]) { seen[k] = true; out.push(r); } }); return out; };
const prods = uniq($('Read Products').all().map(i => i.json).filter(r => r && r.product_id), 'product_id');
const assets = uniq($('Read Launch Assets').all().map(i => i.json).filter(r => r && r.asset_id), 'asset_id');
const want = String(cfg.target_product_id || '').trim();
let p = prods.find(r => String(r.product_id).trim() === want);
if (!p) { p = prods.find(r => String(r.status || '').toLowerCase() === 'new'); }
if (!p) { throw new Error('No product found in the Products tab.'); }
const dedupe = (String(cfg.dedupe_enabled) === 'true') || (cfg.dedupe_enabled === true);
const done = assets.filter(a => String(a.product_id).trim() === String(p.product_id).trim()).length;
const issues = [];
if (dedupe && done > 0) { issues.push(done + ' assets already exist for this product, this run adds another set'); }
const TZ = Number(cfg.tz_offset_minutes) || 330;
const pad = (n) => String(n).padStart(2, '0');
const now = new Date(Date.now() + TZ * 60000);
const fd = (d) => d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate());
const today = fd(now);
const stamp = now.getUTCFullYear() + pad(now.getUTCMonth() + 1) + pad(now.getUTCDate()) + pad(now.getUTCHours()) + pad(now.getUTCMinutes());
let launch = String(p.launch_date || '').trim().slice(0, 10);
if (launch.length !== 10) { launch = fd(new Date(now.getTime() + 7 * 86400000)); }
const lt = Date.parse(launch + 'T00:00:00Z');
const dayNames = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const monNames = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const offsets = [-7, -5, -3, -1, 0, 0, 2, 5, 7];
const plan = ['teaser','story','proof','countdown','launch','launch_social','objection','last_call','thank_you'];
const chan = ['email','social','email','social','email','social','email','email','social'];
const slots = [];
offsets.forEach((o, i) => {
  const d = new Date(lt + o * 86400000);
  const lbl = o === 0 ? 'Launch day' : (o < 0 ? ('T minus ' + Math.abs(o)) : ('T plus ' + o));
  slots.push({ offset: o, date: fd(d), label: lbl, pretty: dayNames[d.getUTCDay()] + ' ' + d.getUTCDate() + ' ' + monNames[d.getUTCMonth()], slot_type: plan[i], channel: chan[i] });
});
return [{ json: { product_id: String(p.product_id), name: String(p.name), tagline: String(p.tagline || ''), category: String(p.category || ''), description: String(p.description || ''), price_inr: Number(p.price_inr) || 0, target_audience: String(p.target_audience || ''), competitors: String(p.competitors || ''), key_features: String(p.key_features || ''), proof_points: String(p.proof_points || ''), launch_date: launch, today: today, stamp: stamp, slots: slots, brand_name: cfg.brand_name, owner_email: cfg.owner_email, owner_name: cfg.owner_name, store_url: cfg.store_url, max_creatives: Number(cfg.max_creatives) || 2, existing_assets: done, data_issues: issues } }];

const textOf = (resp) => { const c = resp && resp.candidates && resp.candidates[0]; const parts = (c && c.content && c.content.parts) || []; return parts.filter(p => typeof p.text === 'string' && !p.thought).map(p => p.text).join(''); };
const parseJson = (raw) => { let t = String(raw || '').trim(); const s = t.indexOf('{'); const e = t.lastIndexOf('}'); if (s !== -1 && e !== -1) t = t.slice(s, e + 1); t = t.replace(/,(\s*[}\]])/g, '$1'); try { return JSON.parse(t); } catch (err) { return null; } };
const P = $('Assemble Product Context').first().json;
const pos = parseJson(textOf($('Positioning Strategist (Gemini)').first().json)) || {};
const lp = parseJson(textOf($('Landing Page Writer (Gemini)').first().json)) || {};
const es = parseJson(textOf($('Email Sequencer (Gemini)').first().json)) || {};
const fo = parseJson(textOf($('FAQ and Objection Writer (Gemini)').first().json)) || {};
const so = parseJson(textOf($input.first().json)) || {};
const issues = Array.isArray(P.data_issues) ? P.data_issues.slice(0) : [];
if (!pos.one_liner) { issues.push('Positioning agent returned nothing, the kit is missing its spine'); }
if (!lp.hero_headline) { issues.push('Landing page agent returned nothing'); }
if (!Array.isArray(es.emails) || es.emails.length === 0) { issues.push('Email sequencer returned nothing'); }
if (!Array.isArray(fo.faqs) || fo.faqs.length === 0) { issues.push('FAQ agent returned nothing'); }
if (!so.linkedin) { issues.push('Social pack agent returned nothing'); }
const emails = Array.isArray(es.emails) ? es.emails : [];
const faqs = Array.isArray(fo.faqs) ? fo.faqs : [];
const objs = Array.isArray(fo.objections) ? fo.objections : [];
const pad = (n) => String(n).padStart(2, '0');
let n = 0;
const assetRows = [];
const addAsset = (type, channel, title, body) => { n += 1; assetRows.push({ asset_id: 'AS' + P.stamp + '-' + pad(n), product_id: P.product_id, created_at: P.today, asset_type: type, channel: channel, title: String(title || ''), body: String(body || '') }); };
addAsset('positioning', 'internal', 'One liner', pos.one_liner || '');
addAsset('positioning', 'internal', 'The enemy', pos.the_enemy || '');
addAsset('positioning', 'internal', 'ICP', pos.icp || '');
addAsset('positioning', 'internal', 'The promise', pos.the_promise || '');
addAsset('positioning', 'internal', 'Category frame', pos.category_frame || '');
addAsset('positioning', 'internal', 'Price justification', pos.price_justification || '');
(Array.isArray(pos.differentiation) ? pos.differentiation : []).forEach((d, i) => { addAsset('positioning', 'internal', 'Differentiator ' + (i + 1), d); });
(Array.isArray(pos.angles) ? pos.angles : []).forEach(a => { addAsset('angle', 'internal', String(a.name || 'Angle'), String(a.hook || '') + ' | lands with: ' + String(a.who_it_lands_with || '')); });
addAsset('landing_page', 'web', 'Hero headline', lp.hero_headline || '');
addAsset('landing_page', 'web', 'Hero subhead', lp.hero_subhead || '');
addAsset('landing_page', 'web', 'Primary CTA', lp.cta_primary || '');
(Array.isArray(lp.benefits) ? lp.benefits : []).forEach(b => { addAsset('landing_page', 'web', String(b.title || 'Benefit'), String(b.line || '')); });
(Array.isArray(lp.how_it_works) ? lp.how_it_works : []).forEach(h => { addAsset('landing_page', 'web', String(h.step || 'Step'), String(h.line || '')); });
emails.forEach(e => { let b = ''; (Array.isArray(e.lines) ? e.lines : []).forEach(l => { b += l + '\n'; }); addAsset('email', 'email', String(e.subject || ''), b.trim()); });
faqs.forEach(f => { addAsset('faq', 'web', String(f.q || ''), String(f.a || '')); });
objs.forEach(o => { addAsset('objection', 'sales', String(o.objection || ''), 'Why: ' + String(o.why_they_say_it || '') + ' | Say: ' + String(o.response || '') + ' | Proof: ' + String(o.proof || '')); });
if (so.linkedin) { let b = ''; (Array.isArray(so.linkedin.lines) ? so.linkedin.lines : []).forEach(l => { b += l + '\n'; }); addAsset('social', 'linkedin', String(so.linkedin.hook || 'LinkedIn post'), b.trim()); }
if (so.instagram) { addAsset('social', 'instagram', 'Instagram caption', String(so.instagram.caption || '') + '\n\n' + (Array.isArray(so.instagram.hashtags) ? so.instagram.hashtags.join(' ') : '')); }
if (Array.isArray(so.x_thread) && so.x_thread.length) { let b = ''; so.x_thread.forEach((x, i) => { b += (i + 1) + '. ' + x + '\n'; }); addAsset('social', 'x', 'X thread', b.trim()); }
if (so.whatsapp) { addAsset('social', 'whatsapp', 'WhatsApp broadcast', String(so.whatsapp.message || '')); }
(Array.isArray(so.ad_hooks) ? so.ad_hooks : []).forEach(a => { addAsset('ad', 'meta', String(a.angle || 'Ad angle'), String(a.hook || '') + '\n' + String(a.body || '')); });
const slots = Array.isArray(P.slots) ? P.slots : [];
const emailBySlot = {};
emails.forEach(e => { emailBySlot[String(e.slot_type || '').trim()] = e; });
const socialCopy = {};
socialCopy.story = so.linkedin ? (String(so.linkedin.hook || '') + '\n\n' + (Array.isArray(so.linkedin.lines) ? so.linkedin.lines.join('\n') : '')) : '';
socialCopy.countdown = so.instagram ? String(so.instagram.caption || '') : '';
socialCopy.launch_social = Array.isArray(so.x_thread) ? so.x_thread.join('\n\n') : '';
socialCopy.thank_you = so.whatsapp ? String(so.whatsapp.message || '') : '';
let m = 0;
const calRows = [];
slots.forEach(s => {
  m += 1;
  let subject = ''; let body = '';
  if (s.channel === 'email') {
    const key = s.slot_type === 'story' ? 'teaser' : s.slot_type;
    const e = emailBySlot[key] || emailBySlot[s.slot_type] || null;
    if (e) { subject = String(e.subject || ''); body = (Array.isArray(e.lines) ? e.lines.join('\n') : ''); }
  } else {
    subject = String(s.slot_type).replace(/_/g, ' ');
    body = socialCopy[s.slot_type] || socialCopy.story || '';
  }
  calRows.push({ item_id: 'CI' + P.stamp + '-' + pad(m), product_id: P.product_id, scheduled_date: s.date, day_label: s.label + ' (' + s.pretty + ')', asset_type: s.slot_type, channel: s.channel, subject: subject, body: body, status: 'scheduled' });
});
const briefs = [];
briefs.push({ label: 'Hero image', purpose: 'landing page hero', idea: String(lp.hero_headline || P.tagline || P.name) });
(Array.isArray(pos.angles) ? pos.angles : []).forEach(a => { briefs.push({ label: String(a.name || 'Angle'), purpose: 'Meta ad creative', idea: String(a.hook || '') }); });
const chosen = briefs.slice(0, Number(P.max_creatives) || 2);
let briefLines = '';
chosen.forEach((b, i) => { briefLines += (i + 1) + '. LABEL: ' + b.label + ' | PURPOSE: ' + b.purpose + ' | IDEA TO ILLUSTRATE: ' + b.idea + '\n'; });
return [{ json: { positioning: pos, landing: lp, emails: emails, faqs: faqs, objections: objs, social: so, asset_rows: assetRows, asset_count: assetRows.length, cal_rows: calRows, cal_count: calRows.length, brief_lines: briefLines, brief_count: chosen.length, data_issues: issues, product: P } }];

const K = $('Assemble Launch Kit').first().json;
const rows = Array.isArray(K.asset_rows) ? K.asset_rows : [];
if (rows.length === 0) { return []; }
return rows.map(r => ({ json: r }));

const K = $('Assemble Launch Kit').first().json;
const rows = Array.isArray(K.cal_rows) ? K.cal_rows : [];
if (rows.length === 0) { return []; }
return rows.map(r => ({ json: r }));

const textOf = (resp) => { const c = resp && resp.candidates && resp.candidates[0]; const parts = (c && c.content && c.content.parts) || []; return parts.filter(p => typeof p.text === 'string' && !p.thought).map(p => p.text).join(''); };
