const K = $('Assemble Launch Kit').first().json;
const P = K.product || {};
const parsed = parseJson(textOf($input.first().json)) || {};
const cre = Array.isArray(parsed.creatives) ? parsed.creatives : [];
if (cre.length === 0) { return []; }
const pad = (n) => String(n).padStart(2, '0');
return cre.map((c, i) => ({ json: { seq: i + 1, label: String(c.label || ('Creative ' + (i + 1))), prompt: String(c.prompt || ''), caption: String(c.caption || ''), file_name: 'creative-' + pad(i + 1) + '.png', product_name: String(P.name || ''), owner_email: String(P.owner_email || ''), total: cre.length } }));

const src = $('Split Prompts').all();
const inputs = $input.all();
const out = [];
inputs.forEach((item, i) => {
  const meta = (src[i] && src[i].json) ? src[i].json : {};
  const resp = item.json || {};
  const c = resp.candidates && resp.candidates[0];
  const parts = (c && c.content && c.content.parts) || [];
  let b64 = '';
  let mime = 'image/png';
  parts.forEach(p => { if (p && p.inlineData && p.inlineData.data) { b64 = String(p.inlineData.data); mime = String(p.inlineData.mimeType || 'image/png'); } });
  if (!b64) { return; }
  out.push({ json: { image_b64: b64, mime_type: mime, label: meta.label, caption: meta.caption, prompt: meta.prompt, file_name: meta.file_name, product_name: meta.product_name, owner_email: meta.owner_email, seq: meta.seq, total: meta.total } });
});
return out;

const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const K = $('Assemble Launch Kit').first().json;
const P = K.product || {};
const lp = K.landing || {};
const pos = K.positioning || {};
const faqs = Array.isArray(K.faqs) ? K.faqs : [];
