let benHtml = '';
(Array.isArray(lp.benefits) ? lp.benefits : []).forEach(b => {
  benHtml += '<td width="33%" valign="top" style="padding:0 10px;"><div style="background:' + WHITE + ';border-radius:10px;padding:22px 20px;border-top:3px solid ' + AMBER + ';"><div style="font-family:Georgia,serif;font-size:18px;font-weight:bold;color:' + DARK + ';margin-bottom:8px;">' + esc(b.title) + '</div><div style="font-size:14px;color:' + INK + ';line-height:1.6;">' + esc(b.line) + '</div></div></td>';
});
