  stepHtml += '<tr><td width="46" valign="top" style="padding:10px 0;"><div style="width:34px;height:34px;background:' + ESP + ';border-radius:17px;color:#FFFFFF;font-family:Georgia,serif;font-size:16px;font-weight:bold;text-align:center;line-height:34px;">' + (i + 1) + '</div></td><td valign="top" style="padding:12px 0 12px 6px;"><div style="font-size:16px;font-weight:bold;color:' + DARK + ';">' + esc(h.step) + '</div><div style="font-size:14px;color:' + INK + ';line-height:1.6;margin-top:3px;">' + esc(h.line) + '</div></td></tr>';
