'<tr><td style="background:' + DARK + ';padding:16px 30px;"><div style="font-family:Georgia,serif;font-size:19px;font-weight:bold;color:' + WHITE + ';letter-spacing:1px;">' + esc(P.brand_name) + '</div></td></tr>' +
