});
const html = '<div style="background:' + CREAM + ';padding:22px;font-family:Calibri,Arial,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="max-width:700px;margin:0 auto;background:' + WHITE + ';border-radius:10px;overflow:hidden;">' +
'<tr><td style="background:' + NAVY + ';padding:24px 26px;"><div style="color:' + AMBER + ';font-size:11px;font-weight:bold;letter-spacing:3px;">LAUNCH KIT READY</div><div style="color:' + WHITE + ';font-family:Georgia,serif;font-size:27px;font-weight:bold;margin-top:7px;">' + esc(P.name) + '</div><div style="color:#D8C4B0;font-size:13px;margin-top:5px;">Rs ' + esc(P.price_inr) + ' &middot; launching ' + esc(P.launch_date) + '</div></td></tr>' + banner +
